//! Loaded-source clones keep a snapshot across original native activation.
use super::*;
fn run(doc:&mut Document,forms:&mut Forms,page:&mut Page,source:&str){assert_eq!(page.console_eval(doc,forms,source).errors,0,"{source}\n{}",page.report());}
fn check(reserve:bool){
 let mut doc=crate::html::parse_loaded_document("<html><body><span id=item data-note=old>original</span><div id=target></div></body></html>",&||Ok(())).unwrap();doc.scripting_enabled=true;let mut forms=Forms::new(&doc);let mut page=Page::new();assert_eq!(page.start(&mut doc,&mut forms,&[]).errors,0);run(&mut doc,&mut forms,&mut page,"var source=document.getElementById('item'),owner=document.implementation.createHTMLDocument('owner');owner.adoptNode(source);var sourceText=source.firstChild;");let Value::Host(source)=page.runtime.execute("source",&mut Bridge{doc:&mut doc,forms:&mut forms,state:&mut page.state}).unwrap()else{panic!("source")};assert!(matches!(page.state.inert_documents.node(source).unwrap().kind,Kind::Parsed{source:ParsedSource::Loaded(_),..}),"must exercise actual loaded payload");let limit=page.state.node_limit;if !reserve{page.state.node_limit=doc.nodes.len();}
 run(&mut doc,&mut forms,&mut page,"var clone=source.cloneNode(true),cloneText=clone.firstChild,list=clone.childNodes;if(clone===source||cloneText===sourceText||clone.ownerDocument!==owner||clone.parentNode!==null||clone.getAttribute('data-note')!=='old'||cloneText.data!=='original')throw 'genuine initial snapshot clone';");let Value::Host(clone)=page.runtime.execute("clone",&mut Bridge{doc:&mut doc,forms:&mut forms,state:&mut page.state}).unwrap()else{panic!("clone")};assert_eq!(clone<FIRST_ENTRY,reserve,"actual native slot versus genuine inert identity");page.state.node_limit=limit;
 run(&mut doc,&mut forms,&mut page,"document.getElementById('target').appendChild(source);source.setAttribute('data-note','changed');sourceText.data='changed';if(source.ownerDocument!==document||source.getAttribute('data-note')!=='changed'||sourceText.data!=='changed')throw 'actual original activation and mutations';if(clone.getAttribute('data-note')!=='old'||cloneText.data!=='original')throw 'loaded clone alias: attribute='+clone.getAttribute('data-note')+', text='+cloneText.data;if(clone.ownerDocument!==owner||clone.childNodes!==list||list[0]!==cloneText||cloneText.ownerDocument!==owner||clone.parentNode!==null)throw 'snapshot identities and original owner retained';clone.setAttribute('data-note','independent');cloneText.data='independent';if(source.getAttribute('data-note')!=='changed'||sourceText.data!=='changed')throw 'clone changes never mutate active original';");
}
#[test]
fn loaded_clone_snapshot_native_reserved_identity_stays_independent(){check(true)}
#[test]
fn loaded_clone_snapshot_without_native_slot_stays_independent(){check(false)}
